"use client";

import type { ReactNode } from "react";
import { motion } from "framer-motion";
import { ArrowRight, Play, Star } from "lucide-react";
import { cn } from "@/lib/utils";

/** Shown until you pass your own `illustration`. Built from theme tokens, so it always fits. */
function Placeholder() {
  return (
    <div className="grid size-full place-items-center p-8">
      <div className="w-full max-w-xs rounded-2xl border bg-card p-4 shadow-sm">
        <div className="flex gap-1.5"><span className="size-2 rounded-full bg-border" /><span className="size-2 rounded-full bg-border" /><span className="size-2 rounded-full bg-border" /></div>
        <div className="mt-4 space-y-2.5">
          <span className="block h-2.5 w-2/3 rounded-full bg-foreground/80" />
          <span className="block h-2 w-full rounded-full bg-muted-foreground/25" />
          <span className="block h-2 w-5/6 rounded-full bg-muted-foreground/25" />
        </div>
        <span className="mt-5 block h-16 rounded-xl bg-primary/10" />
      </div>
    </div>
  );
}

/**
 * A split hero: pitch and buttons on the left, an illustration on the right. Pass any node as
 * `illustration`, such as an <img>, an inline SVG or a Lottie player. It sits in a soft panel with a
 * floating stat chip, and everything eases in on load.
 */
export function HeroSplit({
  badge = "New: version 2 is here",
  title = "Build calmer software, faster",
  text = "A small set of tools that keep your team focused: plan, ship and learn in one place, without the noise.",
  primary = "Get started free",
  secondary = "Watch the tour",
  proof = "Loved by 2,400+ teams",
  chip = "+24% faster",
  illustration,
  className,
}: {
  badge?: string;
  title?: string;
  text?: string;
  primary?: string;
  secondary?: string;
  proof?: string;
  chip?: string;
  /** Any node. An <img> works well. It is centred and contained in the panel. */
  illustration?: ReactNode;
  className?: string;
}) {
  const item = (i: number) => ({ initial: { opacity: 0, y: 16 }, animate: { opacity: 1, y: 0 }, transition: { delay: 0.05 + i * 0.08, duration: 0.5, ease: [0.22, 1, 0.36, 1] as const } });

  return (
    <section className={cn("mx-auto grid w-full max-w-6xl items-center gap-12 px-6 py-16 lg:grid-cols-[1.05fr_1fr] lg:gap-16 lg:py-24", className)}>
      <div>
        <motion.a {...item(0)} href="#" className="group inline-flex items-center gap-2 rounded-full border bg-card py-1 pl-1 pr-3 text-sm transition-colors hover:border-foreground/30">
          <span className="rounded-full bg-primary px-2.5 py-0.5 text-xs font-medium text-primary-foreground">New</span>
          <span className="text-muted-foreground">{badge.replace(/^New:?\s*/i, "")}</span>
          <ArrowRight className="size-3.5 text-muted-foreground transition-transform group-hover:translate-x-0.5" />
        </motion.a>
        <motion.h1 {...item(1)} className="mt-6 text-balance text-5xl font-semibold leading-[1.02] tracking-tight sm:text-6xl">{title}</motion.h1>
        <motion.p {...item(2)} className="mt-5 max-w-lg text-lg leading-relaxed text-muted-foreground">{text}</motion.p>
        <motion.div {...item(3)} className="mt-8 flex flex-wrap items-center gap-3">
          <a href="#" className="inline-flex h-12 items-center gap-2 rounded-full bg-primary px-7 text-sm font-medium text-primary-foreground transition-transform active:scale-95">{primary} <ArrowRight className="size-4" /></a>
          <a href="#" className="inline-flex h-12 items-center gap-2 rounded-full border px-6 text-sm font-medium transition-colors hover:bg-muted active:scale-95"><Play className="size-3.5 fill-current" /> {secondary}</a>
        </motion.div>
        <motion.div {...item(4)} className="mt-10 flex items-center gap-4">
          <div className="flex -space-x-2">
            {["bg-foreground", "bg-primary", "bg-muted-foreground", "bg-foreground/60"].map((c, i) => (
              <span key={i} className={cn("size-8 rounded-full border-2 border-background", c)} />
            ))}
          </div>
          <div className="text-sm">
            <div className="flex gap-0.5 text-foreground">{Array.from({ length: 5 }).map((_, i) => <Star key={i} className="size-3.5 fill-current" />)}</div>
            <p className="mt-0.5 text-muted-foreground">{proof}</p>
          </div>
        </motion.div>
      </div>

      <motion.div initial={{ opacity: 0, scale: 0.96 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: 0.15, duration: 0.7, ease: [0.22, 1, 0.36, 1] }} className="relative">
        <div className="relative aspect-[5/4] overflow-hidden rounded-[2rem] border bg-muted/60 [background-image:radial-gradient(var(--border)_1px,transparent_1px)] [background-size:22px_22px]">
          <div className="absolute inset-0 grid place-items-center p-6 [&_img]:max-h-full [&_img]:w-full [&_img]:object-contain [&_svg]:max-h-full">{illustration ?? <Placeholder />}</div>
        </div>
        <motion.div animate={{ y: [0, -8, 0] }} transition={{ duration: 5, repeat: Infinity, ease: "easeInOut" }} className="absolute -bottom-4 -left-3 rounded-2xl border bg-card px-4 py-3 shadow-lg sm:-left-6">
          <p className="text-xs text-muted-foreground">This quarter</p>
          <p className="text-lg font-semibold tracking-tight">{chip}</p>
        </motion.div>
      </motion.div>
    </section>
  );
}
